export function renderWorldMap(onStart) { const section = document.createElement('section'); section.className = 'world-map'; section.innerHTML = `<div class="logo">Forbidden<br/>Archipelago</div><div class="islands"><span></span><span></span><span class="active"></span></div><article><h1>Green Continent</h1><p>Floating realms are under siege. Enter the first rift and defeat the Dragon-Man and zombie vanguard.</p><button>Start Adventure</button></article>`; section.querySelector('button').onclick = onStart; return section; }
